func TestFleetSchema(t *testing.T) {
	t.Parallel()
	var f Fleet

	const raw = `{"ships":[],"formation":1,"isUnion":false,"fullAirPower":66,"supportTypes":[4],"supportAirPower":58,"supportAswAirPower":58,"enabledAswSupport":false,"tp":0,"mainTP2":0,"escortTP2":0,"tp2":0,"tp3":0,"hasPlane":true,"hasMainPlane":true,"hasJet":false,"fleetAntiAir":3.0769230769230766,"allPlanes":[],"shootDownList":[],"shootDownListAirRaid":[],"unionShootDownList":[],"unionShootDownListAirRaid":[],"allAntiAirCutIn":[],"fleetRosCorr":18,"nightContactRate":0,"fleetSpeed":"高速","airPower":66,"results":[{"airState":{"text":"不発","value":5,"color":"secondary"},"airStateText":"","airStateBarWidth":0,"rates":[0,0,0,0,0,0],"supportRates":[0,0,0,0,0,0],"loopSumAirPower":0,"loopSumEnemyAirPower":0,"loopSumEnemySupportAirPower":0,"avgAirPower":0,"avgEnemyAirPower":0,"avgEnemySupportAirPower":0,"avgDownSlot":0,"avgUsedSteels":0,"isUnknownEnemyAirPower":false}],"mainResult":{},"escortAirPower":0,"result":[]}`

	errList := FleetSchema.Parse(zjson.Decode(bytes.NewReader([]byte(raw))), &f)
	if errList != nil {
		t.Fatal(z.Issues.Prettify(errList))
	}

	// Skip type check
	// assert.Equal(t, nil, f.Ships)

	assert.Equal(t, formation.LINE_AHEAD, f.Formation)
	assert.Equal(t, false, f.IsUnion)
	assert.Equal(t, []supporttype.SupportType{supporttype.NOT_FOUND_DD}, f.SupportTypes)
	assert.Equal(t, int32(58), f.SupportAirPower)
	assert.Equal(t, int32(58), f.SupportAswAirPower)
	assert.Equal(t, false, f.EnabledAswSupport)
	assert.Equal(t, int32(0), f.Tp)
	assert.Equal(t, int32(0), f.MainTP2)
	assert.Equal(t, int32(0), f.EscortTP2)
	assert.Equal(t, int32(0), f.Tp2)
	assert.Equal(t, int32(0), f.Tp3)
	assert.Equal(t, true, f.HasPlane)
	assert.Equal(t, true, f.HasMainPlane)
	assert.Equal(t, false, f.HasJet)
	assert.Equal(t, float64(3.0769230769230766), f.FleetAntiAir)

	// Skip type check
	// assert.Equal(t, nil, f.AllPlanes)
	// assert.Equal(t, nil, f.ShootDownList)
	// assert.Equal(t, nil, f.ShootDownListAirRaid)
	// assert.Equal(t, nil, f.UnionShootDownList)
	// assert.Equal(t, nil, f.UnionShootDownListAirRaid)
	// assert.Equal(t, nil, f.AllAntiAirCutIn)

	assert.Equal(t, int32(18), f.FleetRosCorr)
	assert.Equal(t, int32(0), f.NightContactRate)
	assert.Equal(t, "高速", f.FleetSpeed)
	assert.Equal(t, int32(66), f.AirPower)

	// Skip type check
	// assert.Equal(t, nil, f.Results)
	// assert.Equal(t, nil, f.MainResult)

	assert.Equal(t, int32(0), f.EscortAirPower)
}

